// --- internals ---

// currentPeriod is the index of the period open at the chain head.
func currentPeriod(e *enrollment) int64 {
	return (runtime.ChainHeight() - e.startHeight) / e.periodBlocks
}

// chargeFor prices usage units at the enrollment's copied terms.
func chargeFor(e *enrollment, usage int64) int64 {
	if usage == 0 {
		return 0
	}
	base, ok := mulChecked(usage, e.unitPrice)
	if !ok {
		panic("base overflow")
	}
	c, err := e.sched.Charge(base)
	if err != nil {
		panic("charge: " + err.Error())
	}
	return c
}

// settleElapsed settles the usage accumulator if its period has closed, then
// re-anchors the accumulator on the current period. Exact because usage can
// only ever belong to one period: periods between usagePeriod and now had no
// recorded usage and so owe zero.
func settleElapsed(e *enrollment) {
	cp := currentPeriod(e)
	if cp <= e.usagePeriod {
		return
	}
	settleUsage(e)
	e.usagePeriod = cp
}

// settleUsage charges the accumulator where it stands and moves the funds:
// enrollment deposit -> provider claimable, protocol fee split at the
// enrollment's snapshotted bps. Record's deposit bound is what guarantees the
// withdrawal cannot fail; if that invariant were ever broken the ledger's own
// refusal aborts the whole transaction rather than under-settling.
func settleUsage(e *enrollment) {
	if e.usage == 0 {
		return
	}
	charge := chargeFor(e, e.usage)
	// A zero charge is a LEGAL settlement, not a degenerate one: the realm's
	// own doc recommends a 0-rate first tier for free allowances, and the
	// per-slice floor prices small bases at 0 under positive rates too. The
	// ledger refuses a zero-amount move (feeledger: amount must be positive),
	// so an unconditional MustWithdraw here panics and WEDGES the enrollment
	// forever -- every path to its funds routes through this function. Audit
	// finding R1. The accumulator still clears; nothing is owed, so nothing
	// moves, no period is counted settled and no Settled event is emitted
	// (the event stream carries funds moves, not free usage).
	if charge > 0 {
		ledger.MustWithdraw(enrollKey(e.id), charge)
		credited, fee := ledger.MustDeposit(e.provider.String(), charge, e.feeBps)
		e.periods++
		chain.Emit("Settled",
			"enrollId", itoa(e.id),
			"meterId", itoa(e.meterID),
			"period", itoa(e.usagePeriod),
			"units", itoa(e.usage),
			"charge", itoa(charge),
			"credited", itoa(credited),
			"fee", itoa(fee),
		)
	}
	e.usage = 0
}

func mustGetMeter(id int64) *meter {
	v := metersT.Get(padID(id))
	if v == nil {
		panic("unknown meter " + itoa(id))
	}
	return v.(*meter)
}

func mustGetEnrollment(id int64) *enrollment {
	v := enrollments.Get(padID(id))
	if v == nil {
		panic("unknown enrollment " + itoa(id))
	}
	return v.(*enrollment)
}

// enrollKey is the ledger account an enrollment's deposit lives under. It
// cannot collide with a provider's claimable account: addresses never start
// with '#'.
func enrollKey(id int64) string { return "#enr|" + padID(id) }

// assertNoSend refuses coins on every non-payable entrypoint. Reads the
// ORIGIN envelope, so a transaction that attached coins anywhere is refused
// even if an intermediary consumed them.
func assertNoSend() {
	if !unsafe.OriginSend().IsZero() {
		panic("this function does not accept coins")
	}
}

// counter returns the live-count cell for a, creating it at zero.
func counter(tree *avl.Tree, a address) *int64 {
	k := a.String()
	if v := tree.Get(k); v != nil {
		return v.(*int64)
	}
	n := int64(0)
	tree.Set(k, &n)
	return &n
}

// decCounter decrements a's live count and removes the cell at zero — the
// index must not accumulate dead keys (service_registry's lesson).
func decCounter(tree *avl.Tree, a address) {
	k := a.String()
	v := tree.Get(k)
	if v == nil {
		panic("counter underflow: no cell for " + k)
	}
	n := v.(*int64)
	*n--
	if *n < 0 {
		panic("counter underflow for " + k)
	}
	if *n == 0 {
		tree.Remove(k)
	}
}

// parseInt64List parses a comma-separated int64 list, bounding the element
// count BEFORE materialising values so a thousand-element string dies on
// count, not memory (r/receivables' bounding argument). "" is the empty list.
func parseInt64List(s string, max int, what string) []int64 {
	if s == "" {
		return nil
	}
	var out []int64
	start := 0
	for i := 0; i <= len(s); i++ {
		if i < len(s) && s[i] != ',' {
			continue
		}
		if len(out) >= max {
			panic("too many " + what + "s: at most " + strconv.Itoa(max))
		}
		field := s[start:i]
		start = i + 1
		n, err := strconv.ParseInt(trimSpaces(field), 10, 64)
		if err != nil {
			panic("bad " + what + " " + field + ": " + err.Error())
		}
		out = append(out, n)
	}
	return out
}

func trimSpaces(s string) string {
	i, j := 0, len(s)
	for i < j && s[i] == ' ' {
		i++
	}
	for j > i && s[j-1] == ' ' {
		j--
	}
	return s[i:j]
}

// addChecked / mulChecked are int64 overflow-checked arithmetic. Written here
// rather than imported because they are two lines each and the house keeps
// its payment arithmetic visible at the call site.
func addChecked(a, b int64) (int64, bool) {
	s := a + b
	if (b > 0 && s < a) || (b < 0 && s > a) {
		return 0, false
	}
	return s, true
}

func mulChecked(a, b int64) (int64, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	p := a * b
	if p/b != a {
		return 0, false
	}
	return p, true
}

func padID(id int64) string {
	s := strconv.FormatInt(id, 10)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

// --- Render ---

// Render shows the catalog at "", a meter at "meter/<id>", an enrollment at
// "enroll/<id>". Every user string is sanitized; every list is bounded by
// RenderLimit with the bound stated.
func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case hasPrefix(path, "meter/"):
		return renderMeter(path[len("meter/"):])
	case hasPrefix(path, "enroll/"):
		return renderEnrollment(path[len("enroll/"):])
	default:
		return "unknown path; try \"\", \"meter/<id>\" or \"enroll/<id>\"\n"
	}
}

func renderHome() string {
	out := "# meters — usage-based billing, graduated pricing\n\n"
	out += "Meters: " + itoa(nextMeter) + " · enrollments: " + itoa(nextEnr) +
		" · liabilities: " + itoa(ledger.Liabilities()) + Denom +
		" · fees accrued: " + itoa(ledger.FeesAccrued()) + Denom + "\n\n"
	out += "| id | title | unit | list price | period | status |\n|---|---|---|---|---|---|\n"
	// Newest-first, matching r/subscriptions: under oldest-first a squatter
	// retires 20 early meters once and owns the visible catalog forever;
	// newest-first makes that cost continuous re-creation. Audit finding Y2.
	shown := 0
	metersT.ReverseIterate("", "", func(_ string, v any) bool {
		m := v.(*meter)
		// TableCell, not InlineText: these strings sit between GFM pipes, and
		// InlineText deliberately leaves | literal -- a provider title with a
		// pipe would inject cells and spoof the price and status columns of
		// the one page a consumer reads before enrolling. Audit finding Y1.
		out += "| " + itoa(m.id) + " | " + sanitize.TableCell(m.title) + " | " +
			sanitize.TableCell(m.unit) + " | " + itoa(m.unitPrice) + Denom + " | " +
			itoa(m.periodBlocks) + " blocks | " + m.status + " |\n"
		shown++
		return shown >= RenderLimit
	})
	if nextMeter > int64(shown) {
		out += "\n(first " + itoa(int64(shown)) + " of " + itoa(nextMeter) + " meters)\n"
	}
	return out
}

func renderMeter(idStr string) string {
	id, err := strconv.ParseInt(idStr, 10, 64)
	if err != nil {
		return "bad meter id\n"
	}
	v := metersT.Get(padID(id))
	if v == nil {
		return "unknown meter " + idStr + "\n"
	}
	m := v.(*meter)
	out := "# meter " + itoa(m.id) + " — " + sanitize.InlineText(m.title) + "\n\n"
	out += "- provider: " + m.provider.String() + "\n"
	out += "- unit: " + sanitize.InlineText(m.unit) + " at list " + itoa(m.unitPrice) + Denom + "\n"
	out += "- period: " + itoa(m.periodBlocks) + " blocks · fee: " + itoa(m.feeBps) + " bps · status: " + m.status + "\n"
	out += "- lifetime enrollments: " + itoa(m.enrollments) + "\n\n"
	out += "Schedule over the period base (units × list):\n\n| tier from (base " + Denom + ") | rate (/10000) |\n|---|---|\n"
	edges, rates := m.sched.Edges(), m.sched.Rates()
	lo := int64(0)
	for i, r := range rates {
		out += "| " + itoa(lo) + " | " + itoa(r) + " |\n"
		if i < len(edges) {
			lo = edges[i]
		}
	}
	return out
}

func renderEnrollment(idStr string) string {
	id, err := strconv.ParseInt(idStr, 10, 64)
	if err != nil {
		return "bad enrollment id\n"
	}
	v := enrollments.Get(padID(id))
	if v == nil {
		return "unknown enrollment " + idStr + "\n"
	}
	e := v.(*enrollment)
	pending := chargeFor(e, e.usage)
	out := "# enrollment " + itoa(e.id) + " (meter " + itoa(e.meterID) + ")\n\n"
	out += "- consumer: " + e.consumer.String() + "\n"
	out += "- provider: " + e.provider.String() + "\n"
	out += "- status: " + e.status + " · settled periods: " + itoa(e.periods) + "\n"
	out += "- period " + itoa(currentPeriod(e)) + " open; usage accumulator: " +
		itoa(e.usage) + " units in period " + itoa(e.usagePeriod) + "\n"
	out += "- balance: " + itoa(ledger.BalanceOf(enrollKey(e.id))) + Denom +
		" · pending charge: " + itoa(pending) + Denom + "\n"
	return out
}

func hasPrefix(s, p string) bool {
	return len(s) >= len(p) && s[:len(p)] == p
}

// Realm latefees publishes a graduated late-fee penalty on an overdue invoice
// held in the live [r/invoices]. A creditor (an invoice issuer) declares a
// late-fee SCHEDULE once — a [p/tiers] schedule over how many blocks an
// invoice is overdue — and the realm prices the penalty as a function of that
// overdue duration, escalating by tier. The penalty can be read live
// ([PenaltyNow]) or frozen into a sequence-numbered ASSESSMENT the creditor
// can point a payer to.
//
// It is the fourth consumer of [p/tiers] and the one that exercises its
// "progressive fee" reading over TIME rather than quantity: [r/meters] prices
// usage, [r/payslips] prices withholding, and this prices lateness. It is the
// second consumer of [r/invoices] after [r/receivables], and reads the exact
// integration surface that realm's header advertises — [invoices.InvoiceInfo],
// [invoices.IsOverdue], [invoices.HasInvoice] — all non-crossing views, no
// struct slice crossing a realm boundary.
//
// # It is a PUBLISHER, not a collector
//
// [r/invoices] is live and immutable, so this realm CANNOT add a charge to an
// invoice there, and it holds no coins of its own — no banker, no deposit, no
// payout, no withdrawal path. A published penalty is a verifiable CLAIM backed
// by the invoice's own facts and the creditor's declared schedule, exactly as
// [r/receivables] publishes a loss provision and [r/cashflow] a statement. It
// compels nothing; a debtor who ignores a late fee is in the same position as
// one who ignores the invoice. A custodial variant that collects the fee is a
// separate, larger product and is deliberately out of scope.
//
// # The pricing axis, and the one it is not
//
// The base handed to [p/tiers] is the OVERDUE DURATION in blocks
// (`now - dueHeight`), and each tier's rate is a ugnot accrual per RateScale
// blocks. So the penalty ESCALATES WITH TIME: the longer an invoice is
// overdue, the higher the marginal accrual. [p/tiers]' rate cap makes
// `penalty <= overdueBlocks` an arithmetic fact — the fee can never exceed one
// ugnot per overdue block, a natural ceiling.
//
// It is NOT a percentage of the outstanding amount. [p/tiers] prices one
// amount against breakpoints — a single dimension — and a fee that is both
// time-escalating AND balance-scaled is two dimensions it cannot express in
// one call. The creditor scales the ugnot accrual to their debt magnitudes
// through the schedule; the assessment records the outstanding beside the
// penalty so a reader can compute an effective rate. Composing a balance-
// scaled fee as a single Charge call would be a plausible, wrong number.
//
// # The trust boundary, inherited twice over
//
// A penalty is a self-report of a self-report of a self-report: the issuer set
// the invoice amount in [r/invoices], the due height there, AND the late-fee
// schedule here. This realm computes faithfully from those; it does not
// validate that any of them is fair. A creditor may only assess their OWN
// invoices — [Assess] derives the issuer from `cur.Previous().Address()` and
// reads [invoices.InvoiceInfo] under that key, which returns only invoices
// that address issued.
package latefees

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/tiers"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/invoices"
)

// Denom is the asset the invoices this realm prices are denominated in, and
// the unit a penalty is expressed in. This realm never holds it.
const Denom = "ugnot"

// InvoicesPath pins the realm this one reads, by value, so a reader of a
// published assessment can see which invoices it priced.
const InvoicesPath = invoices.RealmPath

// RenderLimit bounds every rendered list — an unbounded Render was YELLOW in
// three prior audits.
const RenderLimit = 20

// MaxAssessmentsPerIssuer bounds one creditor's stored assessment records, so
// one address cannot grow this realm's state without bound. It counts STORED
// records, the invoices-realm discipline.
const MaxAssessmentsPerIssuer = 256

type assessment struct {
	seq         int64
	issuer      address // the creditor who froze it; the invoice's issuer
	invoiceID   int64
	payer       address
	amount      int64 // invoice face, snapshotted from r/invoices
	paid        int64 // snapshotted
	outstanding int64 // amount - paid at assessment time
	dueHeight   int64
	assessedAt  int64 // chain height the penalty was priced at
	overdueBy   int64 // assessedAt - dueHeight, the base priced
	penalty     int64 // Charge(overdueBy) under the snapshotted schedule
	edges       []int64
	rates       []int64
}

var (
	self      address // this realm's address, captured at deploy
	nextSeq   int64
	schedules = avl.NewTree() // issuer.String()      -> tiers.Schedule (by value)
	bySeq     = avl.NewTree() // padID(seq)            -> *assessment
	issuerNum = avl.NewTree() // issuer.String()       -> *int64, stored assessments
)

func init() {
	self = unsafe.CurrentRealm().Address()
}

// --- creditor side ---

// SetSchedule declares or replaces the caller's late-fee schedule: a graduated
// accrual over OVERDUE BLOCKS, built from comma-separated int64 lists where
// len(rates) == len(edges)+1 and each rate is a ugnot accrual per RateScale
// blocks (0..10000). Edges are block counts — e.g. "216000,648000" is roughly
// ten and thirty days at ~4s blocks. A single rate with no edges is a flat
// accrual. Replacing a schedule does not touch already-frozen assessments,
// which snapshot the schedule that priced them.
func SetSchedule(cur realm, edges, rates string) int {
	assertNoSend()
	issuer := cur.Previous().Address()
	s, err := tiers.New(
		parseInt64List(edges, tiers.MaxTiers-1, "edge"),
		parseInt64List(rates, tiers.MaxTiers, "rate"),
	)
	if err != nil {
		panic("schedule: " + err.Error())
	}
	schedules.Set(issuer.String(), s)
	chain.Emit("ScheduleSet", "issuer", issuer.String(), "tiers", itoa(int64(s.NumTiers())))
	return s.NumTiers()
}

// Assess freezes a late-fee penalty on one of the caller's own overdue
// invoices and returns its sequence number. The caller must be the invoice's
// issuer (the creditor), must have declared a schedule, and the invoice must
// be overdue right now. The invoice's facts and the current schedule are
// snapshotted, so the assessment is a stable claim even as the invoice keeps
// accruing or is later paid.
func Assess(cur realm, invoiceID int64) int64 {
	assertNoSend()
	issuer := cur.Previous().Address()
	if !invoices.HasInvoice(issuer, invoiceID) {
		panic("no invoice " + itoa(invoiceID) + " issued by the caller")
	}
	sv := schedules.Get(issuer.String())
	if sv == nil {
		panic("declare a late-fee schedule first with SetSchedule")
	}
	if !invoices.IsOverdue(issuer, invoiceID) {
		panic("invoice " + itoa(invoiceID) + " is not overdue")
	}
	n := counter(issuerNum, issuer)
	if *n >= MaxAssessmentsPerIssuer {
		panic("per-issuer assessment limit reached")
	}

	payer, amount, paid, dueHeight, _, _ := invoices.InvoiceInfo(issuer, invoiceID)
	now := runtime.ChainHeight()
	overdueBy := now - dueHeight // > 0: IsOverdue required now > dueHeight
	sched := sv.(tiers.Schedule)
	penalty := charge(sched, overdueBy)

	seq := nextSeq
	nextSeq++
	bySeq.Set(padID(seq), &assessment{
		seq:         seq,
		issuer:      issuer,
		invoiceID:   invoiceID,
		payer:       payer,
		amount:      amount,
		paid:        paid,
		outstanding: amount - paid,
		dueHeight:   dueHeight,
		assessedAt:  now,
		overdueBy:   overdueBy,
		penalty:     penalty,
		edges:       sched.Edges(),
		rates:       sched.Rates(),
	})
	*n++

	chain.Emit("Assessed",
		"seq", itoa(seq),
		"issuer", issuer.String(),
		"invoiceId", itoa(invoiceID),
		"payer", payer.String(),
		"overdueBy", itoa(overdueBy),
		"outstanding", itoa(amount-paid),
		"penalty", itoa(penalty),
	)
	return seq
}

// --- views (non-crossing: cross-realm readable) ---

// PenaltyNow is the penalty an issuer's invoice has accrued as of the current
// height, under the issuer's CURRENT schedule. It is 0 when the invoice is not
// overdue — including once it is paid or voided, because [r/invoices] does not
// expose when a payment landed, so accrual is only computable while the
// invoice is still open and late. A frozen [Assess] is how a claim survives
// the invoice being paid. Panics only if the issuer has no schedule or the
// invoice does not exist.
func PenaltyNow(issuer address, invoiceID int64) int64 {
	if !invoices.HasInvoice(issuer, invoiceID) {
		panic("no invoice " + itoa(invoiceID) + " issued by " + issuer.String())
	}
	sv := schedules.Get(issuer.String())
	if sv == nil {
		panic("issuer has no late-fee schedule")
	}
	if !invoices.IsOverdue(issuer, invoiceID) {
		return 0
	}
	_, _, _, dueHeight, _, _ := invoices.InvoiceInfo(issuer, invoiceID)
	return charge(sv.(tiers.Schedule), runtime.ChainHeight()-dueHeight)
}

// QuotePenalty prices a hypothetical overdue duration against an issuer's
// current schedule, without reading any invoice — the preview a creditor uses
// to tune a schedule. Panics if the issuer has no schedule or overdueBlocks is
// negative.
func QuotePenalty(issuer address, overdueBlocks int64) int64 {
	sv := schedules.Get(issuer.String())
	if sv == nil {
		panic("issuer has no late-fee schedule")
	}
	if overdueBlocks < 0 {
		panic("overdueBlocks must be non-negative")
	}
	return charge(sv.(tiers.Schedule), overdueBlocks)
}

// HasSchedule reports whether an issuer has declared a late-fee schedule.
func HasSchedule(issuer address) bool { return schedules.Get(issuer.String()) != nil }

// ScheduleOf returns an issuer's current schedule as its edge and rate slices,
// or two empty slices if none is declared.
func ScheduleOf(issuer address) (edges, rates []int64) {
	sv := schedules.Get(issuer.String())
	if sv == nil {
		return nil, nil
	}
	s := sv.(tiers.Schedule)
	return s.Edges(), s.Rates()
}

// AssessmentInfo returns a frozen assessment's fields. Panics on an unknown
// sequence.
func AssessmentInfo(seq int64) (issuer, payer address, invoiceID, outstanding, overdueBy, penalty, assessedAt int64) {
	a := mustAssessment(seq)
	// invoiceID/outstanding/overdueBy/penalty/assessedAt are int64; issuer and
	// payer are addresses, returned first.
	return a.issuer, a.payer, a.invoiceID, a.outstanding, a.overdueBy, a.penalty, a.assessedAt
}

// AssessmentSchedule returns the schedule snapshot an assessment was priced
// under — the edges and rates frozen with it, which may differ from the
// issuer's current schedule.
func AssessmentSchedule(seq int64) (edges, rates []int64) {
	a := mustAssessment(seq)
	return a.edges, a.rates
}

// HasAssessment reports whether a sequence number names a frozen assessment.
func HasAssessment(seq int64) bool { return bySeq.Get(padID(seq)) != nil }

// AssessmentsOf is the number of assessments an issuer has frozen.
func AssessmentsOf(issuer address) int64 {
	v := issuerNum.Get(issuer.String())
	if v == nil {
		return 0
	}
	return *v.(*int64)
}

func NumAssessments() int64 { return nextSeq }
func Invoices() string      { return InvoicesPath }
func Address() address      { return self }
func Height() int64         { return runtime.ChainHeight() }

// --- internals ---

// charge prices an overdue duration against a schedule, surfacing tiers' own
// error as a panic rather than a silent zero. A zero or negative base prices
// to zero (tiers refuses a negative amount, so it is guarded here).
func charge(s tiers.Schedule, overdueBy int64) int64 {
	if overdueBy <= 0 {
		return 0
	}
	c, err := s.Charge(overdueBy)
	if err != nil {
		panic("charge: " + err.Error())
	}
	return c
}

func mustAssessment(seq int64) *assessment {
	v := bySeq.Get(padID(seq))
	if v == nil {
		panic("unknown assessment " + itoa(seq))
	}
	return v.(*assessment)
}

// assertNoSend refuses coins on every crossing entrypoint. This realm holds
// nothing, so every one of its writes is non-payable. Reads the ORIGIN
// envelope, so a transaction attaching coins anywhere is refused.
func assertNoSend() {
	if !unsafe.OriginSend().IsZero() {
		panic("this function does not accept coins")
	}
}

func counter(tree *avl.Tree, a address) *int64 {
	k := a.String()
	if v := tree.Get(k); v != nil {
		return v.(*int64)
	}
	n := int64(0)
	tree.Set(k, &n)
	return &n
}

// parseInt64List parses a comma-separated int64 list, bounding the element
// count BEFORE materialising values so a long string dies on count, not
// memory (the r/receivables bounding argument). "" is the empty list.
func parseInt64List(s string, max int, what string) []int64 {
	if s == "" {
		return nil
	}
	var out []int64
	start := 0
	for i := 0; i <= len(s); i++ {
		if i < len(s) && s[i] != ',' {
			continue
		}
		if len(out) >= max {
			panic("too many " + what + "s: at most " + strconv.Itoa(max))
		}
		field := s[start:i]
		start = i + 1
		n, err := strconv.ParseInt(trimSpaces(field), 10, 64)
		if err != nil {
			panic("bad " + what + " " + field + ": " + err.Error())
		}
		out = append(out, n)
	}
	return out
}

func trimSpaces(s string) string {
	i, j := 0, len(s)
	for i < j && s[i] == ' ' {
		i++
	}
	for j > i && s[j-1] == ' ' {
		j--
	}
	return s[i:j]
}

func padID(id int64) string {
	s := strconv.FormatInt(id, 10)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

// --- Render ---

// Render shows the catalog at "", an assessment at "seq/<n>", and an issuer's
// schedule at "issuer/<addr>". Every user-supplied value rendered between
// table pipes is escaped with sanitize.TableCell; addresses carry no markdown
// metacharacter but are passed through InlineText for the same reason the
// sibling realms do.
func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case hasPrefix(path, "seq/"):
		return renderAssessment(path[len("seq/"):])
	case hasPrefix(path, "issuer/"):
		return renderIssuer(path[len("issuer/"):])
	default:
		return "unknown path; try \"\", \"seq/<n>\" or \"issuer/<address>\"\n"
	}
}

func renderHome() string {
	out := "# latefees — graduated late-fee penalties over " + sanitize.InlineText(InvoicesPath) + "\n\n"
	out += "Assessments: " + itoa(nextSeq) + ". A penalty is a published CLAIM, not a collected charge; this realm holds no coins.\n\n"
	out += "| seq | issuer | invoice | overdue (blocks) | outstanding | penalty |\n|---|---|---|---|---|---|\n"
	shown := int64(0)
	// Newest-first: the most recent assessments are the ones a reader wants,
	// and oldest-first under a cap lets early seqs own the page forever
	// (r/meters audit finding Y2).
	for seq := nextSeq - 1; seq >= 0 && shown < RenderLimit; seq-- {
		v := bySeq.Get(padID(seq))
		if v == nil {
			continue
		}
		a := v.(*assessment)
		out += "| " + itoa(a.seq) + " | " + sanitize.TableCell(a.issuer.String()) + " | " +
			itoa(a.invoiceID) + " | " + itoa(a.overdueBy) + " | " + itoa(a.outstanding) + Denom +
			" | " + itoa(a.penalty) + Denom + " |\n"
		shown++
	}
	if nextSeq > shown {
		out += "\n(" + itoa(shown) + " most recent of " + itoa(nextSeq) + ")\n"
	}
	return out
}

func renderAssessment(seqStr string) string {
	seq, err := strconv.ParseInt(seqStr, 10, 64)
	if err != nil {
		return "bad sequence\n"
	}
	v := bySeq.Get(padID(seq))
	if v == nil {
		return "unknown assessment " + seqStr + "\n"
	}
	a := v.(*assessment)
	out := "# assessment " + itoa(a.seq) + "\n\n"
	out += "- issuer (creditor): " + a.issuer.String() + "\n"
	out += "- payer (debtor): " + a.payer.String() + "\n"
	out += "- invoice " + itoa(a.invoiceID) + " in " + sanitize.InlineText(InvoicesPath) + "\n"
	out += "- face " + itoa(a.amount) + Denom + ", paid " + itoa(a.paid) + Denom +
		", outstanding " + itoa(a.outstanding) + Denom + "\n"
	out += "- due at height " + itoa(a.dueHeight) + ", assessed at " + itoa(a.assessedAt) +
		" (" + itoa(a.overdueBy) + " blocks overdue)\n"
	out += "- **penalty: " + itoa(a.penalty) + Denom + "**, priced on the overdue duration\n\n"
	out += renderSchedule(a.edges, a.rates)
	return out
}

func renderIssuer(addr string) string {
	issuer := address(addr)
	sv := schedules.Get(addr)
	if sv == nil {
		return "issuer " + sanitize.InlineText(addr) + " has no late-fee schedule\n"
	}
	s := sv.(tiers.Schedule)
	out := "# late-fee schedule for " + sanitize.InlineText(addr) + "\n\n"
	out += "Frozen assessments by this issuer: " + itoa(AssessmentsOf(issuer)) + "\n\n"
	out += renderSchedule(s.Edges(), s.Rates())
	return out
}

func renderSchedule(edges, rates []int64) string {
	out := "Schedule over overdue blocks (ugnot accrued per 10000 blocks, by tier):\n\n"
	out += "| from (blocks overdue) | rate (/10000) |\n|---|---|\n"
	lo := int64(0)
	for i, r := range rates {
		out += "| " + itoa(lo) + " | " + itoa(r) + " |\n"
		if i < len(edges) {
			lo = edges[i]
		}
	}
	return out
}

func hasPrefix(s, p string) bool { return len(s) >= len(p) && s[:len(p)] == p }

// Realm loans is an unsecured term loan with a fixed installment schedule and
// a flat finance charge, holding real ugnot. A LENDER opens a loan to a named
// BORROWER by attaching the principal, which the realm disburses to the
// borrower in the same transaction; the borrower REPAYS over a fixed number of
// installments; each repayment credits the lender's pull-claimable balance,
// the protocol fee splitting off at the ledger. A loan whose installments go
// unpaid past a grace window is permissionlessly DEFAULT-able — a recorded
// state, not a seizure, because v1 is unsecured.
//
// It is the one financial primitive this portfolio never had: CREDIT. The
// accounting realms RECORD obligations (r/invoices, r/receivables — p/aging's
// own doc lists "invoices, loans, dues") and the disbursement realms pay a
// KNOWN TOTAL out on a schedule (r/vesting, r/payroll, r/budgets). A loan is
// the asymmetric opposite: principal OUT once, a LARGER total back over time,
// plus the finance charge and the default state a disbursement realm has no
// use for. See [onyx/r/loans/DISCOVERY.md].
//
// # Custody — the conservation invariant is the product
//
// This is the first custodial realm the factory has selected since the
// publishers (r/latefees, r/cashflow), so the monetary invariant governs it
// exactly as it does r/subscriptions and r/meters:
//
//	Held == Σ lender-claimable + fee pot   (== feeledger.Liabilities())
//
// The principal is NEVER held across a transaction: [Open] receives it and
// pays it out to the borrower in the same call, so the only coins this realm
// ever holds are repayments awaiting the lender's [Claim]. A stuck or
// abandoned loan therefore strands no principal — it was disbursed — and the
// only value at risk is the lender's expected return, which is the real nature
// of unsecured credit and is disclosed, not engineered away.
//
// # The finance charge is FLAT in v1, and that is a scope decision
//
// The total repayable is `principal + floor(principal × rateBps / 10000)` — a
// flat charge over the whole term, NOT compounding and NOT accruing per block.
// Per-installment is `ceil(total / installments)` with the rounding remainder
// on the FINAL installment, so the installments sum to exactly the total (the
// cross-foot). Compounding interest and a tiered-by-duration rate (which
// p/tiers could price) are a v2: pricing them in v1 would add an accrual
// surface whose bugs are the ones lending audits most often find.
//
// # Default is a state, not a seizure — there is no collateral in v1
//
// A borrower past the grace window who has not repaid in full is Default-able
// by anyone (like the sibling realms' valves). It freezes the loan and records
// the shortfall; no coins move, because there is nothing to seize. Secured
// lending is a v2.
//
// REALM-CALLER CAVEAT, inherited from the siblings: coinio's receipt guard
// admits only EOA payers, so the LENDER (who funds Open) and any REPAYER (who
// funds Repay) are EOAs. The BORROWER is a parameter — coinio.Payout delivers
// the principal to any valid address, including a realm — but a realm borrower
// could never Repay (Repay is payable, EOA-only), so naming one is the
// lender's own footgun (an un-repayable gift), not a realm or third-party
// hazard. assertNoSend reads the ORIGIN envelope, so every non-payable
// function refuses any transaction that attached coins anywhere.
package loans

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/coinio"
	"gno.land/p/g1ut6uspuh73e02yauxpmyt8g3wwddaq8utagvm3/feeledger"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
)

// Denom is the only asset this realm accepts.
const Denom = "ugnot"

// MaxFeeBps is the hard protocol-fee cap: 1000 bps = 10%.
const MaxFeeBps = int64(1000)

// Loan status values. Repaid and Defaulted are terminal.
const (
	LoanActive    = "active"
	LoanRepaid    = "repaid"
	LoanDefaulted = "defaulted"
)

// Input bounds.
const (
	// MinPrincipal keeps a loan from being dust; MaxPrincipal keeps
	// principal × rateBps and the total far from int64 overflow (the
	// checked arithmetic still guards it). The lender must ATTACH the
	// principal, so the real ceiling is their balance.
	MinPrincipal = int64(1_000)
	MaxPrincipal = int64(1_000_000_000_000) // 1,000,000 GNOT

	// MaxRateBps caps the flat finance charge at 100% of principal over the
	// whole term. A 0 rate is a legitimate interest-free loan.
	MaxRateBps = int64(10_000)

	// Installment-count and period bounds. The period bounds match the
	// sibling realms: the floor keeps repayment off a per-block treadmill,
	// the ceiling keeps schedule arithmetic far from overflow.
	MinInstallments = int64(1)
	MaxInstallments = int64(60)
	MinPeriodBlocks = int64(10)
	MaxPeriodBlocks = int64(7_500_000)

	// MaxLoansPerLender bounds one lender's stored loans; terminal loans do
	// NOT free the slot, because a Repaid/Defaulted loan is a permanent
	// record a borrower and auditor may need to read.
	MaxLoansPerLender = 50

	// RenderLimit bounds every rendered list — an unbounded Render was
	// YELLOW in three prior audits.
	RenderLimit = 20
)

type loan struct {
	id          int64
	lender      address
	borrower    address
	principal   int64
	total       int64 // principal + finance charge, the sum repayable
	installments int64
	periodBlocks int64
	feeBps      int64 // snapshotted at Open, split off each repayment
	startHeight int64 // disbursement height; installment k due at start + k·period
	repaid      int64 // cumulative repaid toward total
	status      string
}

var (
	admin        address
	pendingAdmin address
	feeRecipient address
	feeBps       int64 // snapshotted into NEW loans

	self    address
	nextID  int64

	loans      = avl.NewTree() // padID(id)        -> *loan
	lenderNum  = avl.NewTree() // lender.String()  -> *int64, stored loans
	ledger     = feeledger.MustNew(MaxFeeBps)
)

func init() {
	admin = unsafe.OriginCaller()
	feeRecipient = admin
	self = unsafe.CurrentRealm().Address()
}

// --- lender side ---

// Open funds a loan: the caller (the lender) attaches the principal, which is
// disbursed to borrower in this same transaction, and the loan is recorded
// with a flat finance charge of rateBps of the principal, repayable over
// `installments` installments of `periodBlocks` blocks each. The current
// protocol fee is snapshotted in. Returns the loan id.
func Open(cur realm, borrower address, rateBps, installments, periodBlocks int64) int64 {
	lender, principal := coinio.Receive(0, cur, Denom)
	if !borrower.IsValid() {
		panic("invalid borrower")
	}
	if borrower == lender {
		panic("lender and borrower must differ")
	}
	if principal < MinPrincipal || principal > MaxPrincipal {
		panic("principal must be " + itoa(MinPrincipal) + ".." + itoa(MaxPrincipal) + Denom)
	}
	if rateBps < 0 || rateBps > MaxRateBps {
		panic("rateBps must be 0.." + itoa(MaxRateBps))
	}
	if installments < MinInstallments || installments > MaxInstallments {
		panic("installments must be " + itoa(MinInstallments) + ".." + itoa(MaxInstallments))
	}
	if periodBlocks < MinPeriodBlocks || periodBlocks > MaxPeriodBlocks {
		panic("periodBlocks must be " + itoa(MinPeriodBlocks) + ".." + itoa(MaxPeriodBlocks))
	}
	charge, ok := mulDivChecked(principal, rateBps, 10_000)
	if !ok {
		panic("finance charge overflow")
	}
	total, ok := addChecked(principal, charge)
	if !ok {
		panic("total overflow")
	}

	n := counter(lenderNum, lender)
	if *n >= MaxLoansPerLender {
		panic("per-lender loan limit reached")
	}

	// Disburse the principal to the borrower in this same transaction, so the
	// realm holds nothing from it. coinio.Payout panics on failure, reverting
	// the receipt above with it.
	coinio.Payout(0, cur, borrower, Denom, principal)

	id := nextID
	nextID++
	loans.Set(padID(id), &loan{
		id:           id,
		lender:       lender,
		borrower:     borrower,
		principal:    principal,
		total:        total,
		installments: installments,
		periodBlocks: periodBlocks,
		feeBps:       feeBps,
		startHeight:  runtime.ChainHeight(),
		status:       LoanActive,
	})
	*n++

	chain.Emit("LoanOpened",
		"loanId", itoa(id),
		"lender", lender.String(),
		"borrower", borrower.String(),
		"principal", itoa(principal),
		"total", itoa(total),
		"installments", itoa(installments),
		"feeBps", itoa(feeBps),
	)
	return id
}

// Claim sends amount ugnot of the caller's claimable balance (repayments
// collected on their loans, net of the protocol fee) back to the caller.
func Claim(cur realm, amount int64) {
	assertNoSend()
	caller := cur.Previous().Address()
	if err := ledger.Withdraw(caller.String(), amount); err != nil {
		panic(err)
	}
	coinio.Payout(0, cur, caller, Denom, amount)
	chain.Emit("Claim", "to", caller.String(), "amount", itoa(amount))
}

// ClaimAll sends the caller's entire claimable balance back to the caller.
func ClaimAll(cur realm) {
	assertNoSend()
	caller := cur.Previous().Address()
	amount, err := ledger.WithdrawAll(caller.String())
	if err != nil {
		panic(err)
	}
	if amount == 0 {
		panic("nothing to claim")
	}
	coinio.Payout(0, cur, caller, Denom, amount)
	chain.Emit("Claim", "to", caller.String(), "amount", itoa(amount))
}

// --- borrower side ---

// Repay pays toward the caller's own loan. The caller must be the loan's
// borrower; the attached amount must be positive and must not exceed the
// outstanding balance. The payment credits the lender's claimable balance (the
// protocol fee splitting off at the ledger); when the cumulative repaid equals
// the total, the loan is Repaid. Repaying ahead of schedule is allowed.
func Repay(cur realm, loanID int64) {
	payer, amount := coinio.Receive(0, cur, Denom)
	l := mustLoan(loanID)
	if payer != l.borrower {
		panic("only the borrower may repay this loan")
	}
	if l.status != LoanActive {
		panic("loan is " + l.status)
	}
	if amount <= 0 {
		panic("attach a positive repayment")
	}
	outstanding := l.total - l.repaid
	if amount > outstanding {
		panic("repayment " + itoa(amount) + " exceeds the outstanding balance " + itoa(outstanding))
	}

	credited, fee := ledger.MustDeposit(l.lender.String(), amount, l.feeBps)
	l.repaid += amount
	if l.repaid == l.total {
		l.status = LoanRepaid
	}

	chain.Emit("Repaid",
		"loanId", itoa(loanID),
		"borrower", l.borrower.String(),
		"amount", itoa(amount),
		"repaidTotal", itoa(l.repaid),
		"credited", itoa(credited),
		"fee", itoa(fee),
		"status", l.status,
	)
}

// Default marks an active loan defaulted once it is past its grace window —
// the final installment's due height plus one more period — and not repaid in
// full. Permissionless by design: no loan's terminal state may depend on
// either party acting. No coins move; the shortfall is recorded.
func Default(cur realm, loanID int64) {
	assertNoSend()
	l := mustLoan(loanID)
	if l.status != LoanActive {
		panic("loan is " + l.status)
	}
	if runtime.ChainHeight() < defaultableAt(l) {
		panic("not defaultable until height " + itoa(defaultableAt(l)))
	}
	l.status = LoanDefaulted
	chain.Emit("Defaulted",
		"loanId", itoa(loanID),
		"lender", l.lender.String(),
		"borrower", l.borrower.String(),
		"shortfall", itoa(l.total-l.repaid),
	)
}

// --- administration (two-step transfer, the house pattern) ---

func SetFeeBps(cur realm, bps int64) {
	assertNoSend()
	if cur.Previous().Address() != admin {
		panic("admin only")
	}
	if bps < 0 || bps > MaxFeeBps {
		panic("fee must be 0.." + itoa(MaxFeeBps) + " bps")
	}
	feeBps = bps
	chain.Emit("FeeSet", "bps", itoa(bps))
}

func SetFeeRecipient(cur realm, recipient address) {
	assertNoSend()
	if cur.Previous().Address() != admin {
		panic("admin only")
	}
	if !recipient.IsValid() {
		panic("invalid recipient")
	}
	feeRecipient = recipient
	chain.Emit("FeeRecipientSet", "to", recipient.String())
}

func WithdrawFees(cur realm) {
	assertNoSend()
	if cur.Previous().Address() != feeRecipient {
		panic("fee recipient only")
	}
	amount := ledger.WithdrawFees()
	if amount == 0 {
		panic("no fees accrued")
	}
	coinio.Payout(0, cur, feeRecipient, Denom, amount)
	chain.Emit("FeesWithdrawn", "to", feeRecipient.String(), "amount", itoa(amount))
}

// SweepDenom recovers out-of-band coins to the fee recipient. For the ledger
// denom the reserve is Liabilities() — lender balances and the fee pot are
// structurally unreachable.
func SweepDenom(cur realm, denom string) {
	assertNoSend()
	if cur.Previous().Address() != feeRecipient {
		panic("fee recipient only")
	}
	reserve := int64(0)
	if denom == Denom {
		reserve = ledger.Liabilities()
	}
	swept := coinio.Sweep(0, cur, feeRecipient, denom, reserve)
	chain.Emit("SurplusSwept", "to", feeRecipient.String(), "coins", itoa(swept)+denom)
}

func TransferAdmin(cur realm, successor address) {
	assertNoSend()
	if cur.Previous().Address() != admin {
		panic("admin only")
	}
	if !successor.IsValid() {
		panic("invalid successor")
	}
	pendingAdmin = successor
	chain.Emit("AdminTransferStaged", "to", successor.String())
}

func AcceptAdmin(cur realm) {
	assertNoSend()
	caller := cur.Previous().Address()
	if pendingAdmin == "" || caller != pendingAdmin {
		panic("no admin transfer staged for caller")
	}
	admin = pendingAdmin
	pendingAdmin = ""
	chain.Emit("AdminTransferred", "to", caller.String())
}

// --- views (non-crossing: cross-realm readable) ---

// LoanInfo returns a loan's terms and state.
func LoanInfo(loanID int64) (lender, borrower address, principal, total, repaid, installments, periodBlocks, startHeight int64, status string) {
	l := mustLoan(loanID)
	return l.lender, l.borrower, l.principal, l.total, l.repaid, l.installments, l.periodBlocks, l.startHeight, l.status
}

// InstallmentAmount is the per-installment amount: ceil(total/installments),
// with the rounding remainder carried on the FINAL installment so the
// installments sum to exactly the total.
func InstallmentAmount(loanID int64) int64 {
	l := mustLoan(loanID)
	return ceilDiv(l.total, l.installments)
}

// Outstanding is total − repaid.
func Outstanding(loanID int64) int64 {
	l := mustLoan(loanID)
	return l.total - l.repaid
}

// ScheduledDue is the cumulative amount that should have been repaid by the
// current height: the sum of every installment whose due height has passed,
// capped at the total. Installment k (1-based) is due at start + k·period.
func ScheduledDue(loanID int64) int64 {
	l := mustLoan(loanID)
	return scheduledDue(l, runtime.ChainHeight())
}

// AmountDueNow is how far behind schedule the borrower is right now:
// ScheduledDue − repaid, floored at zero (a borrower who has prepaid is not
// behind).
func AmountDueNow(loanID int64) int64 {
	l := mustLoan(loanID)
	due := scheduledDue(l, runtime.ChainHeight()) - l.repaid
	if due < 0 {
		return 0
	}
	return due
}

// DefaultableAt is the height at or after which an unpaid loan may be
// Defaulted: the final installment's due height plus one grace period.
func DefaultableAt(loanID int64) int64 { return defaultableAt(mustLoan(loanID)) }

// IsDefaultable reports whether the loan may be Defaulted right now.
func IsDefaultable(loanID int64) bool {
	l := mustLoan(loanID)
	return l.status == LoanActive && runtime.ChainHeight() >= defaultableAt(l) && l.repaid < l.total
}

func HasLoan(loanID int64) bool { return loans.Get(padID(loanID)) != nil }

func LoansOf(lender address) int64 {
	v := lenderNum.Get(lender.String())
	if v == nil {
		return 0
	}
	return *v.(*int64)
}

func Admin() address              { return admin }
func PendingAdmin() address       { return pendingAdmin }
func FeeRecipient() address       { return feeRecipient }
func FeeBps() int64               { return feeBps }
func NumLoans() int64             { return nextID }
func ClaimableOf(a address) int64 { return ledger.BalanceOf(a.String()) }
func FeesAccrued() int64          { return ledger.FeesAccrued() }
func Liabilities() int64          { return ledger.Liabilities() }
func Held() int64                 { return coinio.HeldAt(self, Denom) }
func Address() address            { return self }
func Height() int64               { return runtime.ChainHeight() }

// --- internals ---

// scheduledDue is the cumulative amount owed by `now`: k installments' worth
// where k is how many installment due-heights have passed, capped at total.
func scheduledDue(l *loan, now int64) int64 {
	if now < l.startHeight {
		return 0
	}
	elapsed := (now - l.startHeight) / l.periodBlocks // installments whose due height passed
	if elapsed >= l.installments {
		return l.total
	}
	if elapsed <= 0 {
		return 0
	}
	// k installments of ceil(total/N) each, but never more than the total.
	per := ceilDiv(l.total, l.installments)
	due, ok := mulChecked(per, elapsed)
	if !ok || due > l.total {
		return l.total
	}
	return due
}

// defaultableAt is the final installment's due height plus one grace period.
func defaultableAt(l *loan) int64 {
	return l.startHeight + (l.installments+1)*l.periodBlocks
}

func mustLoan(id int64) *loan {
	v := loans.Get(padID(id))
	if v == nil {
		panic("unknown loan " + itoa(id))
	}
	return v.(*loan)
}

func assertNoSend() {
	if !unsafe.OriginSend().IsZero() {
		panic("this function does not accept coins")
	}
}

func counter(tree *avl.Tree, a address) *int64 {
	k := a.String()
	if v := tree.Get(k); v != nil {
		return v.(*int64)
	}
	n := int64(0)
	tree.Set(k, &n)
	return &n
}

// ceilDiv returns ceil(a/b) for positive b; a,b assumed non-negative and b>0
// (installments >= MinInstallments >= 1).
func ceilDiv(a, b int64) int64 {
	if a <= 0 {
		return 0
	}
	return (a + b - 1) / b
}

func addChecked(a, b int64) (int64, bool) {
	s := a + b
	if (b > 0 && s < a) || (b < 0 && s > a) {
		return 0, false
	}
	return s, true
}

func mulChecked(a, b int64) (int64, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	p := a * b
	if p/b != a {
		return 0, false
	}
	return p, true
}

// mulDivChecked returns floor(a*b/d) without overflowing on the intermediate
// product, by dividing before multiplying where it can and checking the
// product otherwise. Here d is 10000 and a,b are bounded, so the simple
// checked product suffices; the helper names the intent and guards it.
func mulDivChecked(a, b, d int64) (int64, bool) {
	p, ok := mulChecked(a, b)
	if !ok {
		return 0, false
	}
	return p / d, true
}

func padID(id int64) string {
	s := strconv.FormatInt(id, 10)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

func itoa(n int64) string { return strconv.FormatInt(n, 10) }

// --- Render ---

func Render(path string) string {
	switch {
	case path == "":
		return renderHome()
	case hasPrefix(path, "loan/"):
		return renderLoan(path[len("loan/"):])
	default:
		return "unknown path; try \"\" or \"loan/<id>\"\n"
	}
}

func renderHome() string {
	out := "# loans — unsecured term loans with a flat finance charge\n\n"
	out += "Loans: " + itoa(nextID) + " · claimable+fees held: " + itoa(ledger.Liabilities()) + Denom +
		" · fees accrued: " + itoa(ledger.FeesAccrued()) + Denom + "\n\n"
	out += "The realm never holds principal (it is disbursed at Open); the coins it holds are repayments awaiting Claim.\n\n"
	out += "| id | lender | borrower | principal | total | repaid | status |\n|---|---|---|---|---|---|---|\n"
	shown := int64(0)
	for id := nextID - 1; id >= 0 && shown < RenderLimit; id-- {
		v := loans.Get(padID(id))
		if v == nil {
			continue
		}
		l := v.(*loan)
		out += "| " + itoa(l.id) + " | " + sanitize.TableCell(l.lender.String()) + " | " +
			sanitize.TableCell(l.borrower.String()) + " | " + itoa(l.principal) + Denom + " | " +
			itoa(l.total) + Denom + " | " + itoa(l.repaid) + Denom + " | " + l.status + " |\n"
		shown++
	}
	if nextID > shown {
		out += "\n(" + itoa(shown) + " most recent of " + itoa(nextID) + ")\n"
	}
	return out
}

func renderLoan(idStr string) string {
	id, err := strconv.ParseInt(idStr, 10, 64)
	if err != nil {
		return "bad loan id\n"
	}
	v := loans.Get(padID(id))
	if v == nil {
		return "unknown loan " + idStr + "\n"
	}
	l := v.(*loan)
	now := runtime.ChainHeight()
	out := "# loan " + itoa(l.id) + "\n\n"
	out += "- lender: " + l.lender.String() + "\n"
	out += "- borrower: " + l.borrower.String() + "\n"
	out += "- principal " + itoa(l.principal) + Denom + ", total repayable " + itoa(l.total) + Denom +
		" (finance charge " + itoa(l.total-l.principal) + Denom + ")\n"
	out += "- " + itoa(l.installments) + " installments of ~" + itoa(ceilDiv(l.total, l.installments)) +
		Denom + " every " + itoa(l.periodBlocks) + " blocks, from height " + itoa(l.startHeight) + "\n"
	out += "- repaid " + itoa(l.repaid) + Denom + " · outstanding " + itoa(l.total-l.repaid) + Denom +
		" · status " + l.status + "\n"
	if l.status == LoanActive {
		behind := scheduledDue(l, now) - l.repaid
		if behind < 0 {
			behind = 0
		}
		out += "- scheduled-due by now " + itoa(scheduledDue(l, now)) + Denom + " · behind " + itoa(behind) +
			Denom + " · defaultable at height " + itoa(defaultableAt(l)) + "\n"
	}
	return out
}

func hasPrefix(s, p string) bool { return len(s) >= len(p) && s[:len(p)] == p }

// Package counter is the smallest realm that still proves the whole pipeline:
// it is deployed, approved, called with an int and a string, read back through
// Render and through QEval, and made to abort on purpose.
//
// It imports nothing but strconv, deliberately. A smoke test that fails because
// a stdlib package moved between chain versions reports a problem with itself,
// not with the chain, and that is the one failure mode this file must not have.
package counter

import "strconv"

var (
	count int
	note  string
)

// Increment adds n and returns the new total. It panics on a non-positive n,
// which is what the scenario's expect_fail step exercises: a realm that aborts
// is a different outcome from one that is unreachable, and only a real chain
// tells the two apart.
func Increment(cur realm, n int) int {
	if n <= 0 {
		panic("increment must be positive")
	}
	count += n
	return count
}

// SetNote stores a short string, so the scenario covers a string argument
// surviving the round trip through amino and back out of Render.
func SetNote(cur realm, s string) {
	if len(s) > 64 {
		panic("note too long")
	}
	note = s
}

// Get is the QEval target: an int return, read with no gas and no key.
func Get() int { return count }

func Render(path string) string {
	if path == "note" {
		return "note: " + note
	}
	return "count: " + strconv.Itoa(count)
}

// Package ammmath implements integer bonding-curve and constant-product AMM
// helpers for the gnomemepad factory (Pump-style virtual CPMM + real CPMM pool).
package ammmath

import (
	"math/bits"
	"math/overflow"
)

// FeeResult is the split of a gross trade fee.
type FeeResult struct {
	Gross     int64
	Net       int64
	Fee       int64
	Creator   int64
	Protocol  int64
	Remainder int64
}

// maxInt64 is 2^63-1; MulDiv results must fit here.
const maxInt64 = int64(^uint64(0) >> 1)

// MulDiv returns floor((x * y) / d) for x,y >= 0 and d > 0.
// Uses a 128-bit intermediate so mainnet-scale k (VU*VT ≈ 1.1e20) does not overflow.
// Panics on bad domain or if the quotient does not fit in int64.
func MulDiv(x, y, d int64) int64 {
	if x < 0 || y < 0 {
		panic("ammmath: MulDiv negative operand")
	}
	if d <= 0 {
		panic("ammmath: MulDiv non-positive divisor")
	}
	if x == 0 || y == 0 {
		return 0
	}
	if prod, ok := overflow.Mul64(x, y); ok {
		return prod / d
	}
	hi, lo := bits.Mul64(uint64(x), uint64(y))
	// bits.Div64 panics if d == 0 or uint64(d) <= hi (quotient ≥ 2^64).
	quo, _ := bits.Div64(hi, lo, uint64(d))
	if quo > uint64(maxInt64) {
		panic("ammmath: MulDiv result overflow")
	}
	return int64(quo)
}

// ApplyFee takes gross quote paid by the user and feeBPS (e.g. 120 = 1.20%).
func ApplyFee(gross, feeBPS, creatorShareBPS, protocolShareBPS int64) FeeResult {
	if gross <= 0 {
		panic("ammmath: gross must be positive")
	}
	if feeBPS < 0 || feeBPS >= 10000 {
		panic("ammmath: feeBPS out of range")
	}
	if creatorShareBPS < 0 || protocolShareBPS < 0 || creatorShareBPS+protocolShareBPS > 10000 {
		panic("ammmath: fee share BPS invalid")
	}
	fee := gross * feeBPS / 10000
	net := gross - fee
	creator := fee * creatorShareBPS / 10000
	protocol := fee * protocolShareBPS / 10000
	remainder := fee - creator - protocol
	return FeeResult{
		Gross:     gross,
		Net:       net,
		Fee:       fee,
		Creator:   creator,
		Protocol:  protocol,
		Remainder: remainder,
	}
}

// ApplyFeeOnOutput charges fee on assets leaving the pool/curve.
func ApplyFeeOnOutput(grossOut, feeBPS, creatorShareBPS, protocolShareBPS int64) FeeResult {
	if grossOut <= 0 {
		panic("ammmath: grossOut must be positive")
	}
	if feeBPS < 0 || feeBPS >= 10000 {
		panic("ammmath: feeBPS out of range")
	}
	if creatorShareBPS < 0 || protocolShareBPS < 0 || creatorShareBPS+protocolShareBPS > 10000 {
		panic("ammmath: fee share BPS invalid")
	}
	fee := grossOut * feeBPS / 10000
	net := grossOut - fee
	if net <= 0 {
		panic("ammmath: fee consumes entire output")
	}
	creator := fee * creatorShareBPS / 10000
	protocol := fee * protocolShareBPS / 10000
	remainder := fee - creator - protocol
	return FeeResult{
		Gross:     grossOut,
		Net:       net,
		Fee:       fee,
		Creator:   creator,
		Protocol:  protocol,
		Remainder: remainder,
	}
}

// BuyTokens quotes a virtual constant-product buy (net ugnot in).
func BuyTokens(virtualUgnot, virtualToken, ugnotIn int64) (tokensOut, newVU, newVT int64) {
	if ugnotIn <= 0 {
		panic("ammmath: ugnotIn must be positive")
	}
	if virtualUgnot <= 0 || virtualToken <= 0 {
		panic("ammmath: invalid virtual reserves")
	}
	newVU, ok := overflow.Add64(virtualUgnot, ugnotIn)
	if !ok {
		panic("ammmath: virtual ugnot overflow")
	}
	// newVT = floor((VU*VT)/newVU) without materializing k in int64
	newVT = MulDiv(virtualUgnot, virtualToken, newVU)
	if newVT <= 0 {
		panic("ammmath: empty virtual token reserve")
	}
	if newVT >= virtualToken {
		panic("ammmath: zero tokens out")
	}
	tokensOut = virtualToken - newVT
	return tokensOut, newVU, newVT
}

// MaxNetInForTokenOut is the largest net ugnot in that yields tokensOut ≤ maxTokensOut
// (integer CPMM, same floor rules as BuyTokens). Used to fill the last curve tokens
// without panicking when the user sends too much GNOT.
func MaxNetInForTokenOut(virtualUgnot, virtualToken, maxTokensOut int64) int64 {
	if maxTokensOut <= 0 || virtualUgnot <= 0 || virtualToken <= 0 {
		return 0
	}
	if maxTokensOut >= virtualToken {
		return 0
	}
	targetNewVT := virtualToken - maxTokensOut
	// maxNewVU = floor((VU*VT)/targetNewVT)
	maxNewVU := MulDiv(virtualUgnot, virtualToken, targetNewVT)
	if maxNewVU <= virtualUgnot {
		return 0
	}
	return maxNewVU - virtualUgnot
}

// SellTokens quotes a virtual constant-product sell (gross ugnot out).
func SellTokens(virtualUgnot, virtualToken, tokensIn int64) (ugnotOut, newVU, newVT int64) {
	if tokensIn <= 0 {
		panic("ammmath: tokensIn must be positive")
	}
	if virtualUgnot <= 0 || virtualToken <= 0 {
		panic("ammmath: invalid virtual reserves")
	}
	newVT, ok := overflow.Add64(virtualToken, tokensIn)
	if !ok {
		panic("ammmath: virtual token overflow")
	}
	newVU = MulDiv(virtualUgnot, virtualToken, newVT)
	if newVU <= 0 {
		panic("ammmath: empty virtual ugnot reserve")
	}
	if newVU >= virtualUgnot {
		panic("ammmath: zero ugnot out")
	}
	ugnotOut = virtualUgnot - newVU
	return ugnotOut, newVU, newVT
}

// PoolSwapUgnotForToken swaps net ugnot for tokens; remainderToPool adds to ugnot reserve.
func PoolSwapUgnotForToken(poolUgnot, poolToken, ugnotIn, remainderToPool int64) (tokensOut, newPU, newPT int64) {
	if ugnotIn <= 0 {
		panic("ammmath: ugnotIn must be positive")
	}
	if poolUgnot <= 0 || poolToken <= 0 {
		panic("ammmath: invalid pool reserves")
	}
	if remainderToPool < 0 {
		panic("ammmath: negative remainder")
	}
	addU, ok := overflow.Add64(ugnotIn, remainderToPool)
	if !ok {
		panic("ammmath: add overflow")
	}
	newPU, ok = overflow.Add64(poolUgnot, addU)
	if !ok {
		panic("ammmath: pool ugnot overflow")
	}
	den, ok := overflow.Add64(poolUgnot, ugnotIn)
	if !ok {
		panic("ammmath: pool denom overflow")
	}
	tokensOut = MulDiv(poolToken, ugnotIn, den)
	if tokensOut <= 0 {
		panic("ammmath: zero tokens out of pool")
	}
	if tokensOut >= poolToken {
		panic("ammmath: would drain pool tokens")
	}
	newPT = poolToken - tokensOut
	return tokensOut, newPU, newPT
}

// PoolSwapTokenForUgnot swaps tokens for gross ugnot out.
func PoolSwapTokenForUgnot(poolUgnot, poolToken, tokensIn int64) (ugnotOut, newPU, newPT int64) {
	if tokensIn <= 0 {
		panic("ammmath: tokensIn must be positive")
	}
	if poolUgnot <= 0 || poolToken <= 0 {
		panic("ammmath: invalid pool reserves")
	}
	newPT, ok := overflow.Add64(poolToken, tokensIn)
	if !ok {
		panic("ammmath: pool token overflow")
	}
	ugnotOut = MulDiv(poolUgnot, tokensIn, newPT)
	if ugnotOut <= 0 {
		panic("ammmath: zero ugnot out of pool")
	}
	if ugnotOut >= poolUgnot {
		panic("ammmath: would drain pool ugnot")
	}
	newPU = poolUgnot - ugnotOut
	return ugnotOut, newPU, newPT
}

// CanGraduate reports whether raised net ugnot meets the threshold.
func CanGraduate(raisedUgnot, threshold int64) bool {
	return raisedUgnot >= threshold && threshold > 0
}

// SpotPriceUgnotPerToken returns ugnot per token scaled by 1e6 (display only).
func SpotPriceUgnotPerToken(ugnotReserve, tokenReserve int64) int64 {
	if tokenReserve <= 0 {
		return 0
	}
	if ugnotReserve <= 0 {
		return 0
	}
	return MulDiv(ugnotReserve, 1_000_000, tokenReserve)
}

// Package pado is a launchpad template with no trade tax.
//
// One deployment is one realm and one WUGNOT purse. A creator copies this
// package into their own namespace with MsgAddPackage (gno.land/r/<creator>/pado).
// That purse is not padv3 and not any other creator's pad. This package cannot
// spawn those realms itself.
//
// Inside one realm, each token has its own raise target and its own quote
// reserve. Sell and SwapSell pay only from that token's reserve. The bank
// balance is still a single number; the books are what keep launches apart.
//
// Create locks raiseUgnot. Buy and Sell take no fee. At the target, Graduate
// moves that token's quote into an internal pool in this same realm. There is
// no Gnoswap list and no zDex list, and the owner cannot withdraw the raise.
//
// Payment: the user wugnot.Transfer's to this realm, then calls Buy or SwapBuy
// with the same amount. A partial fill leaves the rest as that caller's prepaid
// credit (ClaimWugnot). Pass the amount you transferred. Coins that sit here
// without a Buy can be locked by the next Buy caller, same as padv3.
package pado

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/grc20/v0"
	"gno.land/p/g10ragdr3cjqkael8rslpw4y6rlelhev4h0fswcx/ammmath"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/r/gnoland/wugnot"
)

var (
	launches    avl.Tree // id -> *launch
	bySymbol    avl.Tree // symbol -> id
	nextID      seqid.ID
	nextTokenID seqid.ID

	padAddr address
	owner   address

	prepaid      avl.Tree // caller -> int64 claimable WUGNOT
	totalPrepaid int64

	// testSkipBanker is set only by resetState in tests. Production stays false.
	testSkipBanker bool
	testBank       int64
)

func init(cur realm) {
	padAddr = cur.Address()
	caller := unsafe.OriginCaller()
	if caller.IsValid() {
		owner = caller
	}
}

// Init sets the owner when deploy did not capture one. One shot.
func Init(cur realm) {
	if !cur.Previous().IsUserCall() {
		panic("pado: must be EOA MsgCall")
	}
	if owner.IsValid() {
		panic("pado: owner already set")
	}
	owner = cur.Previous().Address()
	chain.Emit("Owner", "owner", owner.String())
}

// TransferAdmin rotates the launchpad owner. The raise stays in the realm.
func TransferAdmin(cur realm, next address) {
	requireOwner(cur)
	if !next.IsValid() {
		panic("pado: bad owner")
	}
	owner = next
	chain.Emit("Owner", "owner", owner.String())
}

// Create opens one token. raiseUgnot is the quote this curve locks before
// graduate, in ugnot. Only the realm owner may call. The value is fixed here.
func Create(cur realm, name, symbol, uri string, raiseUgnot int64) string {
	requireOwner(cur)
	name = strings.TrimSpace(name)
	symbol = strings.TrimSpace(symbol)
	if len(uri) > MaxURILen {
		panic("pado: uri too long")
	}
	if strings.Contains(uri, "\n") || strings.Contains(uri, "\r") {
		panic("pado: bad uri")
	}
	if bySymbol.Has(symbol) {
		panic("pado: symbol taken")
	}
	vu0, target := seedForRaise(raiseUgnot)
	id := formatID(nextID.Next())
	token, ledger := grc20.NewToken(name, symbol, 0, nextTokenID.Next(), cur)
	l := &launch{
		id:             id,
		name:           name,
		symbol:         symbol,
		uri:            uri,
		creator:        cur.Previous().Address(),
		status:         StatusCurve,
		created:        runtime.ChainHeight(),
		requestedRaise: raiseUgnot,
		raiseUgnot:     target,
		virtualUgnot0:  vu0,
		virtualUgnot:   vu0,
		virtualToken:   VirtualToken0,
		token:          token,
		ledger:         ledger,
	}
	launches.Set(id, l)
	bySymbol.Set(symbol, id)
	chain.Emit("Create",
		"id", id,
		"symbol", symbol,
		"creator", l.creator.String(),
		"requested", strconv.FormatInt(raiseUgnot, 10),
		"raise", strconv.FormatInt(target, 10),
		"virtualUgnot0", strconv.FormatInt(vu0, 10),
	)
	return id
}

// Buy spends up to amount WUGNOT on the curve and mints tokens to the caller.
// No fee. A fill that reaches the raise graduates inside this call.
func Buy(cur realm, id string, amount, minTokensOut int64) int64 {
	payer := requireEOA(cur)
	l := mustLaunch(id)
	if amount <= 0 {
		panic("pado: amount must be positive")
	}
	if minTokensOut < 0 {
		panic("pado: minOut negative")
	}
	creditOrigin(cur)
	lockPrepaid(payer, amount)

	if l.status != StatusCurve {
		panic("pado: not on curve (use SwapBuy)")
	}
	need := l.raiseUgnot - l.raisedUgnot
	left := CurveSupply - l.realSold
	if need <= 0 || left <= 0 {
		if ready(l) {
			graduate(l)
		}
		return 0
	}

	used := amount
	if used > need {
		used = need
	}
	maxIn := ammmath.MaxNetInForTokenOut(l.virtualUgnot, l.virtualToken, left)
	if maxIn <= 0 {
		panic("pado: no curve capacity")
	}
	if used > maxIn {
		used = maxIn
	}
	tokens, _, newVT := ammmath.BuyTokens(l.virtualUgnot, l.virtualToken, used)
	for tokens > left && used > 1 {
		used--
		tokens, _, newVT = ammmath.BuyTokens(l.virtualUgnot, l.virtualToken, used)
	}
	if tokens <= 0 || tokens > left {
		panic("pado: cannot fill curve")
	}
	if minTokensOut > 0 && tokens < minTokensOut {
		panic("pado: tokens below minOut")
	}
	checkSnipe(l, payer, tokens)

	subPrepaid(payer, used)
	l.raisedUgnot += used
	l.virtualUgnot = l.virtualUgnot0 + l.raisedUgnot
	l.virtualToken = newVT
	l.realSold += tokens
	mint(l, payer, tokens)
	chain.Emit("Buy",
		"id", id,
		"buyer", payer.String(),
		"ugnot", strconv.FormatInt(used, 10),
		"tokens", strconv.FormatInt(tokens, 10),
	)
	if ready(l) {
		graduate(l)
	}
	return tokens
}

// Sell burns curve tokens and returns the quote this launch holds. No fee.
// Payout is capped at this launch's raised quote, so a rounding step cannot
// spend another launch's WUGNOT or the virtual seed.
func Sell(cur realm, id string, tokensIn, minUgnotOut int64) int64 {
	seller := requireEOA(cur)
	l := mustLaunch(id)
	if l.status != StatusCurve {
		panic("pado: not on curve (use SwapSell)")
	}
	if tokensIn <= 0 {
		panic("pado: tokensIn must be positive")
	}
	if minUgnotOut < 0 {
		panic("pado: minOut negative")
	}
	if bal(l, seller) < tokensIn {
		panic("pado: insufficient token balance")
	}
	quote, _, newVT := ammmath.SellTokens(l.virtualUgnot, l.virtualToken, tokensIn)
	if quote > l.raisedUgnot {
		quote = l.raisedUgnot
	}
	if quote <= 0 {
		panic("pado: no quote out")
	}
	if minUgnotOut > 0 && quote < minUgnotOut {
		panic("pado: ugnot below minOut")
	}
	l.raisedUgnot -= quote
	l.virtualUgnot = l.virtualUgnot0 + l.raisedUgnot
	l.virtualToken = newVT
	l.realSold -= tokensIn
	if l.realSold < 0 {
		l.realSold = 0
	}
	burn(l, seller, tokensIn)
	payOut(cur, seller, quote)
	chain.Emit("Sell",
		"id", id,
		"seller", seller.String(),
		"tokens", strconv.FormatInt(tokensIn, 10),
		"ugnot", strconv.FormatInt(quote, 10),
	)
	return quote
}

// Graduate moves a filled curve into this realm's internal pool.
// The quote stays on this token's books. Anyone may call it once ready.
func Graduate(cur realm, id string) {
	requireEOA(cur)
	l := mustLaunch(id)
	if l.status != StatusCurve {
		panic("pado: already graduated")
	}
	if !ready(l) {
		panic("pado: not ready to graduate")
	}
	graduate(l)
}

// SwapBuy buys from the post-graduate pool. No fee.
func SwapBuy(cur realm, id string, amount, minTokensOut int64) int64 {
	buyer := requireEOA(cur)
	l := mustLaunch(id)
	if l.status != StatusGraduated {
		panic("pado: not graduated")
	}
	if amount <= 0 {
		panic("pado: amount must be positive")
	}
	if minTokensOut < 0 {
		panic("pado: minOut negative")
	}
	creditOrigin(cur)
	lockPrepaid(buyer, amount)
	tokens, newU, newT := ammmath.PoolSwapUgnotForToken(l.poolUgnot, l.poolToken, amount, 0)
	if minTokensOut > 0 && tokens < minTokensOut {
		panic("pado: tokens below minOut")
	}
	subPrepaid(buyer, amount)
	l.poolUgnot = newU
	l.poolToken = newT
	mint(l, buyer, tokens)
	chain.Emit("SwapBuy",
		"id", id,
		"buyer", buyer.String(),
		"ugnot", strconv.FormatInt(amount, 10),
		"tokens", strconv.FormatInt(tokens, 10),
	)
	return tokens
}

// SwapSell sells into the post-graduate pool. No fee.
// Pays only from this launch's pool quote.
func SwapSell(cur realm, id string, tokensIn, minUgnotOut int64) int64 {
	seller := requireEOA(cur)
	l := mustLaunch(id)
	if l.status != StatusGraduated {
		panic("pado: not graduated")
	}
	if tokensIn <= 0 {
		panic("pado: tokensIn must be positive")
	}
	if minUgnotOut < 0 {
		panic("pado: minOut negative")
	}
	if bal(l, seller) < tokensIn {
		panic("pado: insufficient token balance")
	}
	quote, newU, newT := ammmath.PoolSwapTokenForUgnot(l.poolUgnot, l.poolToken, tokensIn)
	if quote > l.poolUgnot {
		panic("pado: pool quote")
	}
	if minUgnotOut > 0 && quote < minUgnotOut {
		panic("pado: ugnot below minOut")
	}
	l.poolUgnot = newU
	l.poolToken = newT
	burn(l, seller, tokensIn)
	payOut(cur, seller, quote)
	chain.Emit("SwapSell",
		"id", id,
		"seller", seller.String(),
		"tokens", strconv.FormatInt(tokensIn, 10),
		"ugnot", strconv.FormatInt(quote, 10),
	)
	return quote
}

// ClaimWugnot withdraws the caller's prepaid remainder. It does not withdraw
// a launch's raised quote or pool.
func ClaimWugnot(cur realm) int64 {
	user := requireEOA(cur)
	amt := prepaidOf(user)
	if amt <= 0 {
		return 0
	}
	subPrepaid(user, amt)
	payOut(cur, user, amt)
	chain.Emit("ClaimWugnot", "user", user.String(), "amount", strconv.FormatInt(amt, 10))
	return amt
}

// Transfer moves this realm's token. The quote reserve does not move.
func Transfer(cur realm, id string, to address, amount int64) {
	from := requireEOA(cur)
	l := mustLaunch(id)
	if err := l.ledger.Transfer(from, to, amount); err != nil {
		panic(err.Error())
	}
	chain.Emit("Transfer", "id", id, "from", from.String(), "to", to.String(), "amount", strconv.FormatInt(amount, 10))
}

// Approve lets spender TransferFrom the caller's tokens.
func Approve(cur realm, id string, spender address, amount int64) {
	caller := requireEOA(cur)
	l := mustLaunch(id)
	if err := l.ledger.Approve(caller, spender, amount); err != nil {
		panic(err.Error())
	}
}

// TransferFrom spends the caller's allowance.
func TransferFrom(cur realm, id string, from, to address, amount int64) {
	spender := requireEOA(cur)
	l := mustLaunch(id)
	if err := l.ledger.TransferFrom(from, spender, to, amount); err != nil {
		panic(err.Error())
	}
	chain.Emit("TransferFrom", "id", id, "from", from.String(), "to", to.String(), "amount", strconv.FormatInt(amount, 10))
}

