// launch is one token book. token and ledger stay unexported so other
// packages cannot mint.
type launch struct {
	id             string
	name           string
	symbol         string
	uri            string
	creator        address
	status         int
	created        int64
	requestedRaise int64
	raiseUgnot     int64
	virtualUgnot0  int64
	virtualUgnot   int64
	virtualToken   int64
	raisedUgnot    int64
	realSold       int64
	poolUgnot      int64
	poolToken      int64
	leftover       int64
	token          *grc20.Token
	ledger         *grc20.PrivateLedger
	snipe          avl.Tree
}

func seedForRaise(raise int64) (vu0, target int64) {
	if raise < MinRaiseUgnot || raise > MaxRaiseUgnot {
		panic("pado: raise out of range")
	}
	span := VirtualToken0 - CurveSupply
	vu0 = ammmath.MulDiv(raise, span, CurveSupply)
	if vu0 <= 0 {
		panic("pado: raise too small for curve")
	}
	target = ammmath.MulDiv(vu0, CurveSupply, span)
	if target <= 0 || target > raise {
		panic("pado: raise not reachable")
	}
	return vu0, target
}

func ready(l *launch) bool {
	if l.raisedUgnot >= l.raiseUgnot && l.raiseUgnot > 0 {
		return true
	}
	return l.realSold >= CurveSupply && l.raisedUgnot > 0
}

func graduate(l *launch) {
	if l.status != StatusCurve {
		return
	}
	poolU := l.raisedUgnot
	if poolU <= 0 {
		panic("pado: empty pool quote")
	}
	remaining := TotalSupply - l.realSold
	if remaining <= 0 {
		panic("pado: no tokens for pool")
	}
	poolT := remaining
	if l.virtualUgnot > 0 && l.virtualToken > 0 {
		needed := ammmath.MulDiv(poolU, l.virtualToken, l.virtualUgnot)
		if needed > 0 && needed < remaining {
			poolT = needed
		}
	}
	l.poolUgnot = poolU
	l.poolToken = poolT
	l.leftover = remaining - poolT
	l.raisedUgnot = 0
	l.virtualUgnot = 0
	l.virtualToken = 0
	l.status = StatusGraduated
	chain.Emit("Graduated",
		"id", l.id,
		"poolUgnot", strconv.FormatInt(poolU, 10),
		"poolToken", strconv.FormatInt(poolT, 10),
		"leftover", strconv.FormatInt(l.leftover, 10),
	)
}

func requireEOA(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("pado: must be EOA MsgCall")
	}
	caller := cur.Previous().Address()
	if !caller.IsValid() {
		panic("pado: bad caller")
	}
	return caller
}

func requireOwner(cur realm) {
	caller := requireEOA(cur)
	if !owner.IsValid() || caller != owner {
		panic("pado: owner only")
	}
}

func mustLaunch(id string) *launch {
	v := launches.Get(id)
	if v == nil {
		panic("pado: unknown launch")
	}
	l, ok := v.(*launch)
	if !ok || l == nil {
		panic("pado: bad launch")
	}
	return l
}

func bal(l *launch, addr address) int64 {
	if l.token == nil {
		panic("pado: missing token")
	}
	return l.token.BalanceOf(addr)
}

func mint(l *launch, addr address, amount int64) {
	if l.ledger == nil {
		panic("pado: missing ledger")
	}
	if err := l.ledger.Mint(addr, amount); err != nil {
		panic(err.Error())
	}
}

func burn(l *launch, addr address, amount int64) {
	if err := l.ledger.Burn(addr, amount); err != nil {
		panic(err.Error())
	}
}

func checkSnipe(l *launch, buyer address, tokens int64) {
	if runtime.ChainHeight()-l.created >= AntiSnipeHeights {
		return
	}
	maxTok := TotalSupply * AntiSnipeMaxBuyBPS / 10000
	prev := snipeOf(l, buyer)
	if prev+tokens > maxTok {
		panic("pado: anti-snipe max buy")
	}
	l.snipe.Set(buyer.String(), prev+tokens)
}

func snipeOf(l *launch, buyer address) int64 {
	v := l.snipe.Get(buyer.String())
	if v == nil {
		return 0
	}
	n, ok := v.(int64)
	if !ok {
		panic("pado: bad snipe book")
	}
	return n
}

func reservedWugnot() int64 {
	n := totalPrepaid
	launches.Iterate("", "", func(_ string, value any) bool {
		l, ok := value.(*launch)
		if !ok || l == nil {
			panic("pado: bad launch")
		}
		if l.status == StatusCurve {
			n += l.raisedUgnot
		}
		if l.status == StatusGraduated {
			n += l.poolUgnot
		}
		return false
	})
	return n
}

func bankBal() int64 {
	if testSkipBanker {
		return testBank
	}
	return wugnot.BalanceOf(padAddr)
}

func freeWugnot() int64 {
	have := bankBal()
	res := reservedWugnot()
	if have < res {
		panic("pado: reserve exceeds balance")
	}
	return have - res
}

// creditOrigin attributes this tx's ugnot to the caller in tests, where
// OriginSend stands in for a prior wugnot.Transfer.
func creditOrigin(cur realm) {
	if !testSkipBanker {
		return
	}
	sent := unsafe.OriginSend().AmountOf(DenomUgnot)
	if sent < 0 {
		panic("pado: bad origin send")
	}
	if sent == 0 {
		return
	}
	addPrepaid(cur.Previous().Address(), sent)
	testBank += sent
}

func lockPrepaid(user address, amount int64) {
	have := prepaidOf(user)
	if have >= amount {
		return
	}
	need := amount - have
	if freeWugnot() < need {
		panic("pado: transfer WUGNOT to this realm, then buy")
	}
	addPrepaid(user, need)
}

func prepaidOf(addr address) int64 {
	if !addr.IsValid() {
		return 0
	}
	v := prepaid.Get(addr.String())
	if v == nil {
		return 0
	}
	n, ok := v.(int64)
	if !ok {
		panic("pado: bad prepaid book")
	}
	return n
}

func addPrepaid(addr address, amount int64) {
	if amount <= 0 {
		return
	}
	next := prepaidOf(addr) + amount
	prepaid.Set(addr.String(), next)
	totalPrepaid += amount
}

func subPrepaid(addr address, amount int64) {
	if amount <= 0 {
		return
	}
	have := prepaidOf(addr)
	if have < amount {
		panic("pado: prepaid underfunded")
	}
	next := have - amount
	if next == 0 {
		prepaid.Remove(addr.String())
	} else {
		prepaid.Set(addr.String(), next)
	}
	totalPrepaid -= amount
}

func payOut(cur realm, to address, amount int64) {
	if amount <= 0 {
		return
	}
	if freeWugnot() < amount {
		panic("pado: insufficient free WUGNOT")
	}
	if testSkipBanker {
		testBank -= amount
		if testBank < 0 {
			panic("pado: negative test bank")
		}
		return
	}
	wugnot.Transfer(cross(cur), to, amount)
}

func formatID(n seqid.ID) string {
	s := strconv.FormatUint(uint64(n), 10)
	for len(s) < 7 {
		s = "0" + s
	}
	return s
}

package pado

// Curve shape matches padv3 so a 300_000 GNOT raise uses the same virtual seed.
// VirtualUgnot0 is not a constant: Create scales it so the chosen raise is what
// selling CurveSupply locks.
//
//	vu0 = raise * (VirtualToken0 - CurveSupply) / CurveSupply
//	reachable = vu0 * CurveSupply / (VirtualToken0 - CurveSupply)
//
// There is no trade fee. Buy spends the full quote. Sell returns the full quote
// that this launch actually holds.

const (
	TotalSupply   int64 = 1_000_000_000
	CurveSupply   int64 = 800_000_000
	VirtualToken0 int64 = 1_073_000_191

	// Creator-chosen raise, in ugnot. 1 GNOT = 1_000_000 ugnot.
	MinRaiseUgnot int64 = 1_000_000             // 1 GNOT
	MaxRaiseUgnot int64 = 1_000_000_000_000_000 // 1_000_000 GNOT

	// Opening window only. This is a size cap, not a fee.
	AntiSnipeHeights   int64 = 20
	AntiSnipeMaxBuyBPS int64 = 500 // 5% of TotalSupply per address

	MaxURILen = 256

	StatusCurve     = 0
	StatusGraduated = 1

	DenomUgnot = "ugnot"
)

package pado

import (
	"strconv"
	"strings"
)

// Render lists the launches in this realm. Quote figures are ugnot.
func Render(path string) string {
	if path != "" && path != "/" {
		return "> [!WARNING]\n> Path not found"
	}
	var b strings.Builder
	b.WriteString("# pado\n\n")
	b.WriteString("No trade tax. Each launch keeps its own raise.\n\n")
	if owner.IsValid() {
		b.WriteString("* **Owner**: ")
		b.WriteString(owner.String())
		b.WriteString("\n")
	}
	b.WriteString("* **Realm**: ")
	b.WriteString(padAddr.String())
	b.WriteString("\n\n")
	n := 0
	launches.Iterate("", "", func(key string, value any) bool {
		l, ok := value.(*launch)
		if !ok || l == nil {
			return false
		}
		n++
		b.WriteString("## ")
		b.WriteString(esc(l.symbol))
		b.WriteString("\n\n")
		b.WriteString("* **id**: ")
		b.WriteString(esc(key))
		b.WriteString("\n* **raise**: ")
		b.WriteString(strconv.FormatInt(l.raiseUgnot, 10))
		b.WriteString("\n* **raised**: ")
		b.WriteString(strconv.FormatInt(l.raisedUgnot, 10))
		b.WriteString("\n* **pool**: ")
		b.WriteString(strconv.FormatInt(l.poolUgnot, 10))
		b.WriteString("\n* **status**: ")
		b.WriteString(strconv.Itoa(l.status))
		b.WriteString("\n\n")
		return false
	})
	if n == 0 {
		b.WriteString("No launches.\n")
	}
	return b.String()
}

func esc(s string) string {
	r := strings.NewReplacer(
		"\n", " ",
		"\r", " ",
		"#", "",
		"[", "",
		"]", "",
		"<", "",
		">", "",
		"|", "/",
	)
	return r.Replace(s)
}
